/* From Uiverse.io by coding-masala - Tags: loader */
.__UIV_SCOPE__ .loader {
  display: flex;
  justify-content: center;
}

.__UIV_SCOPE__ .loader-bar {
  width: 4px;
  height: 18px;
  margin: 0 8px;
  border-radius: 4px;
  animation: loading_3194 1s ease-in-out infinite;
  background-color: #333;
}

@keyframes loading_3194 {
  0% {
    transform: scale(1);
  }

  20% {
    transform: scaleY(3);
  }

  40% {
    transform: scale(1);
  }
}
